/// `word` may be a citation: the lemma, then any of `verb.pres.3.sg`, `verb.pret.3.sg`, `participle.past` separated by commas.
/// Given parts are output exactly; the rest is predicted to agree with them.
/// Any part may end with markers of the word's own features (`haben`, `sein`), as a
/// dictionary prints them.
pub fn zu_infinitive(word: &str) -> Option<String> {
    German::new().zu_infinitive(word)
}

/// Every candidate for [`zu_infinitive`], most likely first. Confidences sum to the
/// probability that the word has such a form at all.
pub fn zu_infinitive_scored(word: &str) -> Vec<Candidate> {
    German::new().zu_infinitive_scored(word)
}

/// A participle.
///
/// `word` may be a citation: the lemma, then any of `verb.pres.3.sg`, `verb.pret.3.sg`, `participle.past` separated by commas.
/// Given parts are output exactly; the rest is predicted to agree with them.
/// Any part may end with markers of the word's own features (`haben`, `sein`), as a
/// dictionary prints them.
pub fn participle(word: &str, participle: Participle) -> String {
    German::new().participle(word, participle)
}

/// Every candidate for [`participle`], most likely first; confidences sum to 1.
pub fn participle_scored(word: &str, participle: Participle) -> Vec<Candidate> {
    German::new().participle_scored(word, participle)
}

/// A declined article, determiner or pronoun.
pub fn determiner(word: &str, case: Case, agreement: Agreement) -> String {
    German::new().determiner(word, case, agreement)
}

/// Every candidate for [`determiner`], most likely first; confidences sum to 1.
pub fn determiner_scored(word: &str, case: Case, agreement: Agreement) -> Vec<Candidate> {
    German::new().determiner_scored(word, case, agreement)
}

/// The gender of a noun lemma (or citation), with confidence, most likely
/// first. Predicted from the word's shape when it isn't attested.
pub fn gender(word: &str) -> Vec<(Gender, f32)> {
    inherent(0, 0, word, &Gender::ALL)
}

/// The auxiliary of a verb lemma (or citation), with confidence, most likely
/// first. Predicted from the word's shape when it isn't attested.
pub fn auxiliary(word: &str) -> Vec<(Auxiliary, f32)> {
    inherent(2, 0, word, &Auxiliary::ALL)
}

/// Per part of speech: the cells a citation's extra parts fill, and the
/// markers of its inherent features (`m`, `anim`, …).
struct Part {
    citation: &'static [usize],
    markers: &'static [&'static [&'static str]],
}

const PARTS: [Part; 4] = [
    Part {
        citation: &[1],
        markers: &[&["m", "f", "n"]],
    }, // noun
    Part {
        citation: &[145, 146],
        markers: &[],
    }, // adjective
    Part {
        citation: &[4, 10, 53],
        markers: &[&["haben", "sein"]],
    }, // verb
    Part {
        citation: &[],
        markers: &[],
    }, // determiner
];

fn citation<'s>(p: &flexion::Pos<'_, 'static>, pos: usize, word: &'s str) -> flexion::Citation<'s> {
    match PARTS.get(pos) {
        Some(part) => p.citation_marked(word, part.citation, part.markers),
        None => p.citation(word, &[]),
    }
}

fn quick(pos: usize, word: &str, cell: usize, options: Options) -> String {
    match model().and_then(|m| m.pos(pos)) {
        Some(p) => p.best(&citation(&p, pos, word), cell, options),
        None => word.to_string(),
    }
}

fn scored(pos: usize, word: &str, cell: usize, options: Options) -> Vec<Candidate> {
    match model().and_then(|m| m.pos(pos)) {
        Some(p) => p.candidates(&citation(&p, pos, word), cell, options),
        None => vec![Candidate {
            form: word.to_string(),
            confidence: 0.0,
        }],
    }
}

fn optional(pos: usize, word: &str, cell: usize, options: Options) -> Option<String> {
    let p = model()?.pos(pos)?;
    let c = citation(&p, pos, word);
    (p.has_cell(&c, cell) >= 0.5).then(|| p.best(&c, cell, options))
}

fn optional_scored(pos: usize, word: &str, cell: usize, options: Options) -> Vec<Candidate> {
    let Some(p) = model().and_then(|m| m.pos(pos)) else {
        return Vec::new();
    };
    let c = citation(&p, pos, word);
    let exists = p.has_cell(&c, cell);
    let mut out = p.candidates(&c, cell, options);
    for x in &mut out {
        x.confidence *= exists;
    }
    out
}

fn inherent<T: Copy>(pos: usize, feature: usize, word: &str, values: &[T]) -> Vec<(T, f32)> {
    let Some(p) = model().and_then(|m| m.pos(pos)) else {
        return Vec::new();
    };
    let c = citation(&p, pos, word);
    p.inherent(&c, feature)
        .into_iter()
        .filter_map(|(v, q)| values.get(usize::from(v)).map(|&t| (t, q)))
        .collect()
}
